* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; font-size: 16px; color: #f4f0dc; background: #17251e; }
body { min-width: 320px; min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; background: radial-gradient(ellipse at 50% 5%, #304537 0, #17251e 62%); }
.card { width: min(100%, 520px); padding: clamp(24px, 7vw, 44px); border: 1px solid #52634d; border-radius: 18px; background: #202f26; box-shadow: 0 24px 70px #0c1510aa; text-align: center; }
.header { margin-bottom: 28px; }
.pixel-mark { width: 52px; height: 52px; margin: 0 auto 15px; display: grid; place-items: center; border: 2px solid #d9bd72; border-radius: 12px; color: #d9bd72; font-size: 30px; }
.eyebrow { margin: 0 0 6px; color: #d9bd72; font-size: 0.78rem; font-weight: 750; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.4rem); letter-spacing: -.04em; }
.subtitle { margin: 8px 0 0; color: #bdc9b7; }
.board { display: grid; grid-template-columns: 1fr; gap: 0; }
.clock { min-height: 146px; width: 100%; padding: 18px 22px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; border: 2px solid #65745d; border-radius: 14px; color: #17251e; cursor: pointer; transition: transform .14s ease, box-shadow .14s ease, border-color .14s ease; }
.clock-light { background: #eee8d1; }
.clock-dark { background: #aab89d; }
.clock:hover { transform: translateY(-2px); box-shadow: 0 8px 22px #101a13aa; }
.clock:active { transform: scale(.985); }
.clock:focus-visible, .pause-button:focus-visible { outline: 3px solid #e6c96f; outline-offset: 4px; }
.clock.active { border-color: #e4c76e; box-shadow: 0 0 0 3px #e4c76e44, 0 8px 24px #101a13aa; }
.clock.flagged { border-color: #c86754; background: #e4c6b8; }
.player { display: flex; align-items: center; gap: 8px; font-size: 1rem; font-weight: 750; }
.dot { width: 10px; height: 10px; border-radius: 50%; background: #66745a; }
.time { font-variant-numeric: tabular-nums; font-size: clamp(2.7rem, 13vw, 3.5rem); font-weight: 800; letter-spacing: .025em; line-height: 1.05; }
.clock-hint { min-height: 1em; color: #52614d; font-size: .72rem; font-weight: 800; letter-spacing: .14em; }
.divider { position: relative; z-index: 1; height: 0; display: flex; justify-content: center; }
.divider span { position: relative; top: -12px; padding: 3px 10px; border: 1px solid #52634d; border-radius: 20px; background: #202f26; color: #c5ceb9; font-size: .68rem; font-weight: 800; letter-spacing: .12em; }
.status { min-height: 28px; margin: 20px 0 14px; color: #e2c978; font-weight: 700; }
.pause-button { min-width: 148px; min-height: 48px; padding: 10px 20px; border: 1px solid #d9bd72; border-radius: 10px; background: #d9bd72; color: #17251e; font: inherit; font-weight: 800; cursor: pointer; transition: background .15s ease, transform .15s ease; }
.pause-button:hover { background: #ead58f; }
.pause-button:active { transform: scale(.97); }
.pause-button span { margin-left: 7px; }
.footer-note { margin: 22px 0 0; color: #9eae9b; font-size: .86rem; }
@media (max-width: 380px) { .card { padding: 22px 18px; } .clock { min-height: 132px; } }

const START_MS = 5 * 60 * 1000;
const clocks = {
  white: { button: document.querySelector('#white-clock'), display: document.querySelector('#white-time'), hint: document.querySelector('#white-hint'), remaining: START_MS },
  black: { button: document.querySelector('#black-clock'), display: document.querySelector('#black-time'), hint: document.querySelector('#black-hint'), remaining: START_MS }
};
const status = document.querySelector('#status');
const pauseButton = document.querySelector('#pause-button');
let active = null;
let startedAt = 0;
let flagged = false;

function format(ms) {
  const totalSeconds = Math.ceil(ms / 1000);
  return `${Math.floor(totalSeconds / 60)}:${String(totalSeconds % 60).padStart(2, '0')}`;
}

function paint() {
  for (const [name, clock] of Object.entries(clocks)) {
    clock.display.textContent = format(clock.remaining);
    clock.button.classList.toggle('active', active === name);
    clock.button.setAttribute('aria-pressed', String(active === name));
    clock.button.setAttribute('aria-label', `${name === 'white' ? 'White' : 'Black'} clock, ${format(clock.remaining)} remaining. Tap to start or switch turns.`);
    clock.hint.textContent = flagged && active === name ? 'FLAGGED' : active === name ? 'YOUR TURN' : active ? 'WAITING' : name === 'white' ? 'TAP TO START' : 'WAITING';
  }
}

function update() {
  if (active === null || flagged) return;
  const clock = clocks[active];
  clock.remaining = Math.max(0, clock.remaining - (performance.now() - startedAt));
  startedAt = performance.now();
  if (clock.remaining === 0) {
    flagged = true;
    status.textContent = `${active === 'white' ? 'White' : 'Black'} Flag!`;
    clock.button.classList.add('flagged');
    active = null;
    pauseButton.disabled = true;
    paint();
    return;
  }
  paint();
}

function selectSide(name) {
  if (flagged) return;
  update();
  if (flagged) return;
  active = name;
  startedAt = performance.now();
  status.textContent = `${name === 'white' ? 'White' : 'Black'} to move`;
  pauseButton.disabled = false;
  pauseButton.innerHTML = 'Ⅱ <span>Pause</span>';
  pauseButton.setAttribute('aria-label', 'Pause clock');
  paint();
}

for (const [name, clock] of Object.entries(clocks)) {
  clock.button.addEventListener('click', () => selectSide(name));
}
pauseButton.addEventListener('click', () => {
  if (flagged) return;
  if (active !== null) {
    update();
    if (flagged) return;
    active = null;
    status.textContent = 'Paused';
    pauseButton.innerHTML = '▶ <span>Resume</span>';
    pauseButton.setAttribute('aria-label', 'Resume clock');
    paint();
  } else {
    status.textContent = 'Tap a side to start';
  }
});

window.setInterval(update, 100);
paint();
